css:
:scope{display:block;width:100%}
.pw{--bg:#0F0E0C;--tx:#EDE6D8;--lb:#C2B8A6;--rl:#8E4A30;--hl:#3A3531;--bb:#8E4A30;--bt:#EDE6D8;--ol:#C2B8A6;background:var(--bg);color:var(--tx);font-family:var(--os-font-body);font-weight:400}
.pw[data-ground="bone"]{--bg:#EDE6D8;--tx:#0F0E0C;--lb:#3A3531;--rl:#8E4A30;--hl:#3A3531;--bb:#0F0E0C;--bt:#EDE6D8;--ol:#0F0E0C}
.pw[data-ground="umber"]{--bg:#3A3531;--tx:#EDE6D8;--lb:#C2B8A6;--rl:#C2B8A6;--hl:#C2B8A6;--bb:#EDE6D8;--bt:#0F0E0C;--ol:#C2B8A6}
.pw[data-ground="oxblood"]{--bg:#4A1C18;--tx:#EDE6D8;--lb:#C2B8A6;--rl:#C2B8A6;--hl:#C2B8A6;--bb:#EDE6D8;--bt:#0F0E0C;--ol:#C2B8A6}
.pw[data-ground="clay"]{--bg:#8E4A30;--tx:#EDE6D8;--lb:#EDE6D8;--rl:#EDE6D8;--hl:#EDE6D8;--bb:#0F0E0C;--bt:#EDE6D8;--ol:#EDE6D8}
.pw[data-ground="olive"]{--bg:#3C402F;--tx:#EDE6D8;--lb:#C2B8A6;--rl:#C2B8A6;--hl:#C2B8A6;--bb:#EDE6D8;--bt:#0F0E0C;--ol:#C2B8A6}
.pw__in{box-sizing:content-box;max-width:1200px;margin:0 auto;padding:112px 32px}
.pw__kicker{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.3em;text-transform:uppercase;color:var(--lb)}
.pw__rule{width:64px;height:2px;background:var(--rl);margin:28px 0 32px}
.pw__in>.pw__rule:first-child{margin-top:0}
.pw__h2{margin:0;font-family:var(--os-font-heading);font-weight:500;font-size:60px;line-height:1.08;color:var(--tx);text-wrap:balance}
.pw__h2[data-size="large"]{font-size:64px;line-height:1.05}
.pw__intro{margin:24px 0 0;font-size:21px;line-height:1.5;max-width:36em}
.pw__grid{display:grid;gap:40px;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));margin-top:64px}
.pw__card{border-top:1px solid var(--hl);padding-top:28px}
.pw__em{display:none}
.pw__card:has(.pw__em){border-top-color:var(--tx)}
.pw__ic{color:var(--lb);line-height:0}
.pw__ic svg{display:none}
.pw__ic[data-icon="circle"] .i-circle,.pw__ic[data-icon="power-over"] .i-over{display:block}
.pw__ic[data-icon="power-with"] .i-with{display:block;color:var(--rl)}
.pw__ic[data-icon="none"],.pw__ic:not([data-icon]){display:none}
.pw__cic{line-height:0}.pw__cic img{display:block;width:56px;height:56px;object-fit:contain}
.pw__label{margin:0;font-family:var(--os-font-label);font-weight:400;font-size:13px;letter-spacing:.3em;text-transform:uppercase;color:var(--lb)}
.pw__def{margin:14px 0 0;font-family:var(--os-font-heading);font-weight:500;font-size:28px;line-height:1.2;color:var(--tx)}
.pw__body{margin:14px 0 0;font-size:21px;line-height:1.5;color:var(--tx)}
.pw__close{margin:56px 0 0;font-family:var(--os-font-heading);font-style:italic;font-weight:500;font-size:30px;line-height:normal;color:var(--tx)}
.pw__close[data-size="large"]{font-size:34px;line-height:1.2}
.pw__btn{display:inline-block;margin-top:48px;font-family:var(--os-font-label);font-weight:400;font-size:12px;letter-spacing:.22em;text-transform:uppercase;text-decoration:none;line-height:normal;cursor:pointer}
.pw__btn--primary{background:var(--bb);color:var(--bt);padding:18px 28px}
.pw__btn--outline{border:1px solid var(--ol);color:var(--tx);padding:16px 24px}
.pw__btn:focus-visible{outline:2px solid var(--tx);outline-offset:3px}
.pw[data-style="terms"] .pw__label{font-size:14px;color:var(--tx);margin-top:18px}
.pw[data-style="terms"] .pw__body{font-size:19px}
.pw[data-style="terms"] .pw__close{margin-top:64px}
.pw[data-style="columns"] .pw__grid{margin-top:56px}
.pw[data-style="columns"] .pw__card{padding-top:24px}
.pw[data-style="columns"] .pw__card:has(.pw__em) .pw__label{color:var(--tx)}
.pw[data-style="compact"] .pw__grid{margin-top:56px;gap:32px;grid-template-columns:repeat(auto-fit,minmax(260px,1fr))}
.pw[data-style="compact"] .pw__card{padding-top:20px}
.pw[data-style="compact"] .pw__label{color:var(--tx)}
.pw[data-style="compact"] .pw__body{margin-top:12px;font-size:20px;line-height:1.45}
@media (max-width:767px){
.pw__in{padding:56px 20px}
.pw__kicker{font-size:11px}
.pw__rule{width:48px;margin:24px 0 24px}
.pw__h2,.pw__h2[data-size="large"]{font-size:40px;line-height:1.1}
.pw__intro{font-size:19px;margin-top:20px}
.pw__grid,.pw[data-style="columns"] .pw__grid,.pw[data-style="compact"] .pw__grid{grid-template-columns:1fr;gap:28px;margin-top:36px}
.pw__def{font-size:23px}
.pw__body,.pw[data-style="terms"] .pw__body,.pw[data-style="compact"] .pw__body{font-size:19px}
.pw__close,.pw__close[data-size="large"],.pw[data-style="terms"] .pw__close{font-size:27px;margin-top:40px}
.pw__btn{margin-top:36px}
}
